import { defineSchema, defineTable } from "convex/server";
import { v } from "convex/values";

export default defineSchema({
  webhooks: defineTable({
    payload: v.string(),
    runId: v.string(),
  }),
});

import { query, internalMutation } from "./_generated/api";
import { v } from "convex/values";
import { internalQuery, internalMutation as internalMutationFn } from "./_generated/server";

// Internal mutation to insert a webhook record (called from HTTP action)
export const insertWebhook = internalMutationFn({
  args: {
    payload: v.string(),
    runId: v.string(),
  },
  handler: async (ctx, args) => {
    await ctx.db.insert("webhooks", {
      payload: args.payload,
      runId: args.runId,
    });
  },
});

// Query to get webhook records by runId
export const get_webhook = query({
  args: {
    runId: v.string(),
  },
  handler: async (ctx, args) => {
    return await ctx.db
      .query("webhooks")
      .filter((q) => q.eq(q.field("runId"), args.runId))
      .collect();
  },
});

import { httpRouter } from "convex/server";
import { httpAction } from "./_generated/server";
import { internal } from "./_generated/api";

const http = httpRouter();

http.route({
  path: "/webhook",
  method: "POST",
  handler: httpAction(async (ctx, request) => {
    const body = await request.json();

    const { payload, runId } = body as { payload: string; runId: string };

    if (!payload || !runId) {
      return new Response(
        JSON.stringify({ error: "Missing required fields: payload and runId" }),
        {
          status: 400,
          headers: { "Content-Type": "application/json" },
        }
      );
    }

    await ctx.runMutation(internal.webhooks.insertWebhook, {
      payload,
      runId,
    });

    return new Response(
      JSON.stringify({ success: true }),
      {
        status: 200,
        headers: { "Content-Type": "application/json" },
      }
    );
  }),
});

export default http;

